"""20-T GF64 and 65-T GF4096 inverses from a derived cubic GF4 norm.

The Boolean certificate is generated by checks/derive_cubic130.py using
only field arithmetic and linear algebra. Zero maps to zero. Input words
and arbitrary dirty bystanders are preserved, and all measurement phases
are repaid before return. No input promise, history, or classical mask is
required by the public inverse functions.
"""
from functools import cache

import kickmix as km

from field_tensor import apply_linear, invert_binary_columns, symmetric_tensor
from quantum_reciprocal import xor_linear
from scalar_inverse_phase import operand_basis
from tower_inverse import (apply_inplace_linear, quadratic_basis, init_norm,
                           erase_norm, xor_product, phase_product, kernel)
from low_space_inverse import erase_norm_original_basis


# Index convention for all affine forms: bit0 is1, bits1..6 are source,
# bits7..14 are the eight quadratic gates; bits15..17 are norm products.
QUADRATIC_GATES = ((1, 2), (29, 46), (30, 47), (4, 11),
                   (16, 38), (27, 34), (5, 33), (8, 17))
NORM_GATES = ((28, 28369), (48, 18562), (44, 9833))
NORM_OUTPUTS = (196798, 105560)
ADJUGATE_OUTPUTS = (11164, 9386, 20848, 20696, 16278, 23904)


@cache
def cubic_data():
    field, small = km.GF2Field(6), km.GF2Field(2)
    beta = next(x for x in range(2, 64) if field.mul(x, x) ^ x ^ 1 == 0)
    theta = next(x for x in range(2, 64) if field.pow(x, 3) ^ x ^ 1 == 0)
    columns = tuple(field.mul(field.pow(theta, i), 1 if j == 0 else beta)
                    for i in range(3) for j in range(2))
    to_cubic = invert_binary_columns(columns)
    # Reassembly is x^20 * Norm(x)^2; GF4 inverse is squaring even at0.
    adjugate_forms = tuple(_combine(ADJUGATE_OUTPUTS, row) for row in to_cubic)
    assert all(not (form & 1) for form in adjugate_forms)
    square_columns = tuple(small.mul(1 << bit, 1 << bit) for bit in range(2))
    square_rows = tuple(sum(((value >> out) & 1) << bit
                            for bit, value in enumerate(square_columns)) for out in range(2))
    reassembly = []
    for component in range(3):
        for a, b, weight in symmetric_tensor(2, small):
            left = _combine(adjugate_forms[2 * component:2 * component + 2], a) >> 1
            right = _combine(square_rows, b)
            output = _combine(columns[2 * component:2 * component + 2], weight)
            reassembly.append((left, right, output))
    assert len(reassembly) == 9
    for value in range(64):
        known = 1 | (value << 1)
        for j, (a, b) in enumerate(QUADRATIC_GATES):
            known |= (((a & value).bit_count() & 1) &
                      ((b & value).bit_count() & 1)) << (7 + j)
        adjugate = sum(((mask & known).bit_count() & 1) << bit
                       for bit, mask in enumerate(ADJUGATE_OUTPUTS))
        extended = known
        for j, (a, b) in enumerate(NORM_GATES):
            extended |= (((a & value).bit_count() & 1) &
                         ((b & known).bit_count() & 1)) << (15 + j)
        norm = sum(((mask & extended).bit_count() & 1) << bit
                   for bit, mask in enumerate(NORM_OUTPUTS))
        embedded = (norm & 1) ^ (beta if norm & 2 else 0)
        assert adjugate == field.pow(value, 20)
        assert embedded == field.pow(value, 21)
        reconstructed = 0
        for a, b, output in reassembly:
            if ((a & (known >> 1)).bit_count() & 1) and ((b & norm).bit_count() & 1):
                reconstructed ^= output
        assert reconstructed == (field.invert(value) if value else 0)
    return dict(beta=beta, theta=theta, columns=columns,
                to_cubic=to_cubic, reassembly=tuple(reassembly))


def _combine(items, mask):
    result = 0
    for j, value in enumerate(items):
        if mask >> j & 1:
            result ^= value
    return result


def _view_pair(builder, signals, left, right):
    rows, undo = operand_basis(len(signals), left, right)
    view = km.array(signals)
    apply_inplace_linear(builder, view, rows)
    return view, undo


def _xor_affine(builder, signals, target, form):
    if form & 1:
        builder.x(target)
    for j, source in enumerate(signals):
        if form >> (j + 1) & 1:
            builder.cx(source, target)


def _emit_same_source_product(builder, signals, target, left, right, weight,
                              *, right_constant=False, measured=False):
    view, undo = _view_pair(builder, signals, left, right)
    if right_constant:
        builder.x(view[1])
    selected = [target[j] for j in range(len(target)) if weight >> j & 1]
    if measured:
        for bit in selected:
            builder.ccz(bit, view[0], view[1])
    else:
        pivot = selected[0]
        for bit in selected[1:]:
            builder.cx(pivot, bit)
        builder.ccx(view[0], view[1], pivot)
        for bit in reversed(selected[1:]):
            builder.cx(pivot, bit)
    if right_constant:
        builder.x(view[1])
    apply_inplace_linear(builder, view, undo)


def init_cubic_scaffold(builder, source):
    """Build8 quadratic parents and2 norm bits in11 T, preserving source."""
    assert len(source) == 6
    cubic_data()
    quadratics = builder.alloc_qubits(8)
    for j, (a, b) in enumerate(QUADRATIC_GATES):
        view, undo = _view_pair(builder, list(source), a, b)
        builder.init_and(view[0], view[1], quadratics[j])
        apply_inplace_linear(builder, view, undo)
    signals = [*source, *quadratics]
    norm = builder.alloc_qubits(2)
    for bit, mask in enumerate(NORM_OUTPUTS):
        _xor_affine(builder, signals, norm[bit], mask & ((1 << 15) - 1))
    for j, (a, b) in enumerate(NORM_GATES):
        weight = sum(((mask >> (15 + j)) & 1) << bit
                     for bit, mask in enumerate(NORM_OUTPUTS))
        _emit_same_source_product(builder, signals, norm, a, b >> 1, weight,
                                  right_constant=bool(b & 1))
    return dict(quadratics=quadratics, norm=norm)


def erase_cubic_scaffold(builder, source, scaffold):
    """Erase all ten scaffold bits with parents present, at zero T."""
    quadratics, norm = scaffold['quadratics'], scaffold['norm']
    signals = [*source, *quadratics]
    masks = builder.alloc_bits(2)
    builder.hmr(norm, masks)
    builder.free(norm)
    for bit, mask in enumerate(NORM_OUTPUTS):
        if mask & 1:
            builder.cz(masks[bit], True)
        for j, signal in enumerate(signals):
            if mask >> (j + 1) & 1:
                builder.cz(masks[bit], signal)
    for j, (a, b) in enumerate(NORM_GATES):
        weight = sum(((mask >> (15 + j)) & 1) << bit
                     for bit, mask in enumerate(NORM_OUTPUTS))
        _emit_same_source_product(builder, signals, masks, a, b >> 1, weight,
                                  right_constant=bool(b & 1), measured=True)
    builder.free(masks)
    for j, (a, b) in reversed(list(enumerate(QUADRATIC_GATES))):
        view, undo = _view_pair(builder, list(source), a, b)
        builder.del_and(view[0], view[1], quadratics[j])
        apply_inplace_linear(builder, view, undo)
    builder.free(quadratics)


def _reassemble(builder, source, target, scaffold, *, measured=False):
    signals = km.array([*source, *scaffold['quadratics']])
    norm = scaffold['norm']
    from field_tensor import parity_pivot
    for a, b, output in cubic_data()['reassembly']:
        left = parity_pivot(builder, signals, a)
        right = parity_pivot(builder, norm, b)
        selected = [target[j] for j in range(len(target)) if output >> j & 1]
        if measured:
            for bit in selected:
                builder.ccz(bit, left, right)
        else:
            pivot = selected[0]
            for bit in selected[1:]:
                builder.cx(pivot, bit)
            builder.ccx(left, right, pivot)
            for bit in reversed(selected[1:]):
                builder.cx(pivot, bit)
        parity_pivot(builder, norm, b)
        parity_pivot(builder, signals, a)


def init_inverse_six_cubic(builder, source, target, zero_flag=None):
    """XOR inverse(source) into arbitrary target; return ten live parents."""
    assert len(source) == len(target) == 6
    assert not set(source) & set(target)
    scaffold = init_cubic_scaffold(builder, source)
    if zero_flag is not None:
        norm = scaffold['norm']
        builder.x(norm)
        builder.ccx(norm[0], norm[1], zero_flag)
        builder.x(norm)
    _reassemble(builder, source, target, scaffold)
    return scaffold


def inverse_six_cubic(builder, source, target=None, zero_flag=None):
    """20-T clean XOR inverse; optional coherent zero flag adds1 T."""
    if target is None:
        target = builder.alloc_qubits(6)
    scaffold = init_inverse_six_cubic(builder, source, target, zero_flag)
    erase_cubic_scaffold(builder, source, scaffold)
    return target


def erase_inverse_six_with_scaffold(builder, source, target, scaffold):
    """Erase a clean inverse output while its reassembly parents stay live."""
    measured = builder.alloc_bits(6)
    builder.hmr(target, measured)
    _reassemble(builder, source, measured, scaffold, measured=True)
    builder.free(measured)


def compact_inverse_twelve(builder, source, zero_flag=None):
    """Return an allocated GF4096 inverse in65 T and24 peak extra qubits."""
    info = quadratic_basis(12)
    apply_inplace_linear(builder, source, info['to_tower'])
    left, right = source[:6], source[6:]
    norm = init_norm(builder, left, right, info['delta'])
    inverse_norm = inverse_six_cubic(builder, norm, zero_flag=zero_flag)
    target = builder.alloc_qubits(12)
    builder.cx(right, left)
    xor_product(builder, left, inverse_norm, target[:6])
    builder.cx(right, left)
    xor_product(builder, right, inverse_norm, target[6:])
    apply_inplace_linear(builder, target, info['from_tower'])
    erase_norm_original_basis(builder, target, inverse_norm)
    builder.free(inverse_norm)
    erase_norm(builder, left, right, norm, info['delta'])
    builder.free(norm)
    apply_inplace_linear(builder, source, info['from_tower'])
    return target


def phase_inverse_twelve_35(builder, source, mask_in_tower_basis):
    """Conservative35-T phase using cubic child; this is not a27-T claim."""
    info = quadratic_basis(12)
    apply_inplace_linear(builder, source, info['to_tower'])
    left, right = source[:6], source[6:]
    norm = init_norm(builder, left, right, info['delta'])
    inverse_norm = builder.alloc_qubits(6)
    scaffold = init_inverse_six_cubic(builder, norm, inverse_norm)
    builder.cx(right, left)
    phase_product(builder, left, inverse_norm, mask_in_tower_basis[:6], kernel(6))
    builder.cx(right, left)
    phase_product(builder, right, inverse_norm, mask_in_tower_basis[6:], kernel(6))
    erase_inverse_six_with_scaffold(builder, norm, inverse_norm, scaffold)
    builder.free(inverse_norm)
    erase_cubic_scaffold(builder, norm, scaffold)
    erase_norm(builder, left, right, norm, info['delta'])
    builder.free(norm)
    apply_inplace_linear(builder, source, info['from_tower'])


@cache
def _trace_product_terms():
    field = km.GF2Field(6)
    def trace(value):
        result = 0
        for _ in range(6):
            result ^= value
            value = field.mul(value, value)
        assert result in (0, 1)
        return result
    return tuple((a, b, sum(trace(field.mul(1 << bit, weight)) << bit
                             for bit in range(6)))
                 for a, b, weight in kernel(6))


def _phase_trace_triple(builder, left, right, third):
    from field_tensor import parity_pivot
    for a, b, c in _trace_product_terms():
        first = parity_pivot(builder, left, a)
        second = parity_pivot(builder, right, b)
        last = parity_pivot(builder, third, c)
        builder.ccz(first, second, last)
        parity_pivot(builder, third, c)
        parity_pivot(builder, right, b)
        parity_pivot(builder, left, a)


def phase_inverse_trace_twelve(builder, denominator, numerator):
    """Apply(-1)^Tr(numerator/denominator) in65 T with22 scratch.

    Both quantum inputs are preserved and disjoint; zero denominator has
    inverse0. The ten cubic parents remain live for zero-T inverse erasure.
    This is the variable-numerator phase, not the27-T classical-mask phase.
    """
    assert len(denominator) == len(numerator) == 12
    assert not set(denominator) & set(numerator)
    info = quadratic_basis(12)
    apply_inplace_linear(builder, denominator, info['to_tower'])
    apply_inplace_linear(builder, numerator, info['to_tower'])
    left, right = denominator[:6], denominator[6:]
    num_left, num_right = numerator[:6], numerator[6:]
    norm = init_norm(builder, left, right, info['delta'])
    inverse_norm = builder.alloc_qubits(6)
    scaffold = init_inverse_six_cubic(builder, norm, inverse_norm)
    # Relative trace of z/a is (z_left*a_right+z_right*a_left)/Norm(a).
    _phase_trace_triple(builder, right, inverse_norm, num_left)
    _phase_trace_triple(builder, left, inverse_norm, num_right)
    erase_inverse_six_with_scaffold(builder, norm, inverse_norm, scaffold)
    builder.free(inverse_norm)
    erase_cubic_scaffold(builder, norm, scaffold)
    erase_norm(builder, left, right, norm, info['delta'])
    builder.free(norm)
    apply_inplace_linear(builder, numerator, info['from_tower'])
    apply_inplace_linear(builder, denominator, info['from_tower'])
